import{_ as a,a as t}from"./chunks/ecosystem.BHQSxcYD.js";import{_ as r,o,c as i,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function d(l,e,h,c,p,m){return o(),i("div",null,[...e[0]||(e[0]=[n('<img src="'+a+'" style="zoom:70%;"><br><h2 id="what-is-xdrip" tabindex="-1">What is xDrip? <a class="header-anchor" href="#what-is-xdrip" aria-label="Permalink to &quot;What is xDrip?&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>xDrip is an unofficial and independent Android app which works as a data hub and processor between many different devices.</p><p>It supports wireless connections to G6, One, One+, G7, Stelo, CareSens Air, Libre via NFC and Bluetooth, Aidex, Guardian, Simplera, Medtronic pumps, Eversense CGM, Libre 2 and 3, as well as many other CGM/pump vendor apps (Pasta, iCan, CamAPS, Equil G, Vitatok, Glucotech, SiSensing, and more) via the companion app notification reader. It also supports Bluetooth glucose meters such as the Contour Next One, AccuChek Guide, Verio Flex &amp; Diamond Mini, as well as devices like the Pendiq 2.0 Insulin Pen.</p><p>Heart-rate and step counter data is processed from Android Wear, Garmin, Fitbit and Pebble smart-watches and watch-faces for those that show glucose values and graphs.</p><p>The app contains sophisticated charting, customization and data entry features as well as a predictive simulation model.</p><p>Instant two-way synchronization is possible by linking follower handsets; data can also be uploaded and downloaded to a Nightscout web service or uploaded directly to Nocturne, Tidepool, MongoDB or InfluxDB.</p><p>Customization allows for different options to configure alarms, vocalize readings, change the display preferences etc. International users can update translations from within the app too.</p><p>Your data is yours and can be exported in many different ways. xDrip also intercommunicates with other apps, for example sending and receiving live data with <a href="https://androidaps.readthedocs.io/en/latest/index.html" target="_blank" rel="noreferrer">AndroidAPS</a>.</p><br><h2 id="ready-to-start-continue-here" tabindex="-1"><a href="./install/usethedoc.html">Ready to start? Continue here!</a> <a class="header-anchor" href="#ready-to-start-continue-here" aria-label="Permalink to &quot;[Ready to start? Continue here!](./install/usethedoc)&quot;">​</a></h2><br><h2 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h2><p><a href="https://github.com/StephenBlackWasAlreadyTaken/DexDrip" target="_blank" rel="noreferrer">DexDrip</a> was created by Emma Black in 2014 and then became <a href="http://stephenblackwasalreadytaken.github.io/xDrip/" target="_blank" rel="noreferrer">xDrip</a>, an app collecting CGM data from a G4 receiver or a bridge device and sending them to <a href="https://nightscout.github.io/" target="_blank" rel="noreferrer">Nightscout</a>. It also came with the follower app <a href="http://stephenblackwasalreadytaken.github.io/NightWatch/" target="_blank" rel="noreferrer">Nightwatch</a> (obsolete).</p><p>This project was then modified by @jamorham to become <a href="https://jamorham.github.io/#xdrip-plus" target="_blank" rel="noreferrer">xDrip</a>.</p><blockquote><p><em>Personal research version of xDrip</em></p></blockquote><img src="https://avatars.githubusercontent.com/u/12565568" style="zoom:33%;"><br><h2 id="disclaimer-and-warning" tabindex="-1"><strong>Disclaimer And Warning</strong> <a class="header-anchor" href="#disclaimer-and-warning" aria-label="Permalink to &quot;**Disclaimer And Warning**&quot;">​</a></h2><ul><li><strong>Use xDrip at your own risk, and do not use the information or code to make medical decisions.</strong></li><li>Use of <a href="https://github.com/NightscoutFoundation/xDrip" target="_blank" rel="noreferrer">code from github.com</a> is without warranty or formal support of any kind. Please review the repository’s <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/LICENSE" target="_blank" rel="noreferrer">LICENSE</a> for details.</li><li>All product and company names, trademarks, service marks, registered trademarks, and registered service marks are the property of their respective holders.</li></ul><p><strong>Please note:</strong> this project has no association with and is not endorsed by: Abbott Laboratories, Aidex, Ascenia, i-Sens, Companion Medical, Dexcom, Medtronic, Lifescan, Medtrum, Pendiq, Roche, Senseonics, Sibionics, GlucoRx.</p>',23)])])}const g=r(s,[["render",d]]);export{b as __pageData,g as default};
